import json
import re

transcript_path = "/Users/huncho/.gemini/antigravity-ide/brain/80c2d294-d8d4-46e4-bb1b-160fa56b5bdc/.system_generated/logs/transcript_full.jsonl"

def find_betting_container(node):
    if not isinstance(node, dict):
        return None

    attributes = node.get("attributes", {})
    if attributes.get("id") == "betting__container" or attributes.get("id") == "sportsbook" or "betting" in str(attributes.get("id")):
        return node

    # Also check by class name if needed
    for child in node.get("children", []):
        res = find_betting_container(child)
        if res:
            return res
    return None

def print_tree(node, depth=0):
    if not isinstance(node, dict):
        return

    tag = node.get("nodeName", node.get("tagName", "unknown")).lower()
    attrs = node.get("attributes", {})
    class_name = attrs.get("className", attrs.get("class", ""))
    node_id = attrs.get("id", "")

    attr_str = f" id='{node_id}'" if node_id else ""
    attr_str += f" class='{class_name}'" if class_name else ""

    # Print the tag and its attributes
    print("  " * depth + f"<{tag}{attr_str}>")

    for child in node.get("children", []):
        print_tree(child, depth + 1)

with open(transcript_path, "r", encoding="utf-8") as f:
    for line in f:
        if "browser_get_dom" in line or "betting__container" in line:
            try:
                data = json.loads(line)
                # Let's see if the content contains DOM info
                content = data.get("content", "")
                if not content and "tool_calls" in data:
                    continue
                # Sometimes DOM is in content
                # Let's search if there's any dictionary structure representing DOM
                # The browser_get_dom tool returns JSON representing the DOM
                if isinstance(content, str) and "betting__container" in content:
                    # Let's see if we can parse the content as JSON or if it contains JSON
                    # Wait, let's look for JSON patterns
                    matches = re.findall(r"\{.*\}", content)
                    for m in matches:
                        try:
                            json_obj = json.loads(m)
                            container = find_betting_container(json_obj)
                            if container:
                                print("Found container in string!")
                                print_tree(container)
                                break
                        except:
                            pass

                # Check tool outputs or responses
                # The step object might have a content representing the DOM
                if "content" in data and isinstance(data["content"], str):
                    try:
                        # Let's try to extract JSON from content
                        # Wait, browser_get_dom returns a DOM tree JSON string
                        # Let's try loading it directly
                        parsed_content = json.loads(data["content"])
                        container = find_betting_container(parsed_content)
                        if container:
                            print("Found container in parsed content!")
                            print_tree(container)
                    except:
                        pass
            except Exception as e:
                pass
